SELECT COUNT(*) AS compared_rows, COUNTIF(a.location_id IS NULL OR g.location_id IS NULL OR a.expected_net_revenue IS DISTINCT FROM g.expected_net_revenue OR a.reported_net_revenue IS DISTINCT FROM g.reported_net_revenue OR a.status IS DISTINCT FROM g.status) AS mismatches
FROM actual a FULL OUTER JOIN gold g ON a.location_id=g.location_id AND a.report_date=g.report_date;
